document.addEventListener("DOMContentLoaded",()=>{document.body.insertAdjacentHTML("afterbegin",'<div id="scroll-progress" class="fixed top-0 left-0 h-1 bg-supernova-orange z-[100] transition-all duration-150" style="width: 0%"></div>');const t=document.getElementById("scroll-progress");document.body.insertAdjacentHTML("beforeend",'\n        <div id="sticky-cta" class="fixed bottom-6 left-1/2 -translate-x-1/2 z-[80] transform translate-y-24 opacity-0 transition-all duration-500 w-full max-w-xs px-4 lg:hidden">\n            <a href="https://forms.gle/GgNmqWUd55QvW8BU6" target="_blank" \n                class="block w-full bg-supernova-orange text-white font-bold py-4 rounded-full text-center shadow-2xl hover:bg-orange-600 active:scale-95 transition-all">\n                Enroll Your Child Now\n            </a>\n        </div>\n    ');const e=document.getElementById("sticky-cta");window.addEventListener("scroll",()=>{const n=(document.body.scrollTop||document.documentElement.scrollTop)/(document.documentElement.scrollHeight-document.documentElement.clientHeight)*100;t.style.width=n+"%",n>20?(e.classList.remove("translate-y-24","opacity-0"),e.classList.add("translate-y-0","opacity-100")):(e.classList.add("translate-y-24","opacity-0"),e.classList.remove("translate-y-0","opacity-100"))},{passive:!0})});